<script setup>import{Link,router}from'@inertiajs/vue3';import AdminLayout from'../../../Layouts/AdminLayout.vue';import Pagination from'../../../Components/Pagination.vue';defineProps({products:Object,categories:Array,filters:Object,counts:Object});const destroy=p=>confirm(`Move ${p.name} to Trash?`)&&router.delete(`/admin/products/${p.slug}`),restore=p=>router.post(`/admin/products/${p.id}/restore`);</script><template><AdminLayout><div class="flex items-end justify-between"><div><p class="section-kicker">Catalogue</p><h1 class="section-title">Products</h1></div><Link href="/admin/products/create" class="btn-primary">Add product</Link></div><div class="mt-5 flex gap-2 text-sm"><Link href="/admin/products" class="btn-light">Active {{counts.active}}</Link><Link href="/admin/products?view=trash" class="btn-light">Trash {{counts.trash}}</Link></div><div class="card mt-5 overflow-x-auto"><table class="admin-table"><thead><tr><th>Product</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="p in products.data" :key="p.id"><td><div class="flex items-center gap-3"><img :src="p.image_url" class="h-12 w-12 rounded-[8px] object-cover"><div><b>{{p.name}}</b><p class="text-xs text-slate-500">{{p.sku}} · {{p.category?.name}}</p></div></div></td><td>TZS {{Number(p.current_price).toLocaleString()}}</td><td><span :class="p.low_stock?'font-black text-amber-600':''">{{p.track_stock?p.stock_quantity:'∞'}}</span></td><td class="capitalize">{{p.status}}</td><td><div class="flex gap-2"><Link v-if="!p.deleted_at" :href="`/admin/products/${p.slug}/edit`" class="text-sm font-bold text-prinx-600">Edit</Link><button v-if="!p.deleted_at" class="text-sm font-bold text-red-600" @click="destroy(p)">Trash</button><button v-else class="text-sm font-bold text-emerald-600" @click="restore(p)">Restore</button></div></td></tr></tbody></table></div><Pagination :links="products.links"/></AdminLayout></template>
